package pl.zagranietyper.parser;import java.text.Normalizer;import java.util.*;import java.util.regex.*;
public final class FootballTeamToAdvanceSyntaxAdapter {private static final Pattern AGAINST=Pattern.compile("^awans[: ]+(.+?) z (.+)$");private static final Pattern[]P={Pattern.compile("^awans[: ]+(.+)$"),Pattern.compile("^(.+?) awans(?:uje)?(?: do .+| dalej)?$"),Pattern.compile("^(.+?) zakwalifikuje sie dalej$")};private final FootballParticipantResolver resolver=new FootballParticipantResolver();public Result parse(String title,String home,String away){String n=norm(title);if(!n.contains("awans")&&!n.contains("zakwalif"))return new Result(Status.NOT_LIKE,null,null);if(n.contains("w reg czasie")||n.contains("w regulaminowym"))return new Result(Status.OTHER,null,null);var against=AGAINST.matcher(n);if(against.matches()){var selected=resolve(against.group(1),home,away);var opponent=resolve(against.group(2),home,away);if((selected==FootballParticipantResolver.Resolution.HOME&&opponent==FootballParticipantResolver.Resolution.AWAY)||(selected==FootballParticipantResolver.Resolution.AWAY&&opponent==FootballParticipantResolver.Resolution.HOME))return new Result(Status.PARSED,against.group(1),selected);return new Result(Status.PARTICIPANT_UNRESOLVED,null,null);}for(var p:P){var m=p.matcher(n);if(!m.matches())continue;String subject=m.group(1).trim();var r=resolve(subject,home,away);return new Result(r==FootballParticipantResolver.Resolution.HOME||r==FootballParticipantResolver.Resolution.AWAY?Status.PARSED:Status.PARTICIPANT_UNRESOLVED,subject,r);}return new Result(Status.OTHER,null,null);}private FootballParticipantResolver.Resolution resolve(String s,String h,String a){return resolver.resolve(s,h,a,FootballParticipantResolver.MatchingPolicy.STRICT_SCORED_SUBSET,Map.of());}private static String norm(String s){return Normalizer.normalize(s.replace('ł','l').replace('Ł','L'),Normalizer.Form.NFD).replaceAll("\\p{M}+","").toLowerCase(Locale.ROOT).replaceAll("^[^\\p{L}\\p{N}]+","").replaceAll("[^\\p{L}\\p{N}: ]+"," ").replaceAll("\\s+"," ").trim();}public enum Status{PARSED,NOT_LIKE,PARTICIPANT_UNRESOLVED,OTHER}public record Result(Status status,String subject,FootballParticipantResolver.Resolution side){public boolean parsed(){return status==Status.PARSED;}}}
